<?php
function count_condition_upload($id,$rows,$filename){
 $b=count_batch($id);if(in_array($b['status'],['Applied','Cancelled','Reversed'],true))throw new Exception('This count is closed.');$header=find_header_row($rows,[['Master SKU','Product Description','On Hand','Actual Good','Actual Damaged','Remarks']]);if($header===null)return count_upload_legacy($id,$rows,$filename);
 $errors=[];$values=[];$known=[];$seen=[];foreach(count_lines($id) as $l)$known[$l['master_sku']]=$l;
 if(($rows[0][0]??'')!=='Physical Inventory Count'||trim($rows[0][1]??'')!==$b['batch_ref'])$errors[]='Use the original downloaded count sheet.';
 $columns=array_flip(array_map('norm',$rows[$header]));
 foreach(array_slice($rows,$header+1) as $i=>$row){if(!array_filter($row,fn($v)=>trim((string)$v)!==''))continue;$n=$header+$i+2;$sku=trim($row[$columns['master sku']]??'');if(!isset($known[$sku])){$errors[]="Row $n: unknown SKU.";continue;}if(isset($seen[$sku])){$errors[]="Row $n: duplicate SKU $sku.";continue;}$seen[$sku]=true;$l=$known[$sku];$on=trim($row[$columns['on hand']]??'');if(!is_numeric($on)||(float)$on!=(int)$l['on_hand'])$errors[]="Row $n: On Hand snapshot was changed.";
  $good=trim($row[$columns['actual good']]??'');$damage=trim($row[$columns['actual damaged']]??'');if($good===''&&$damage==='')continue;
  if(!preg_match('/^\d{1,8}$/D',$good)||!preg_match('/^\d{1,8}$/D',$damage)){$errors[]="Row $n: enter both Good and Damaged as whole numbers; use 0 for zero.";continue;}
  $remarks=trim($row[$columns['remarks']]??'');$gd=(int)$good-(int)$l['sellable_on_hand'];$dd=(int)$damage-(int)$l['nonsellable_on_hand'];if(($gd||$dd)&&strlen($remarks)<3)$errors[]="Row $n: remarks are required for a condition or quantity discrepancy.";
  $values[$l['id']]=[(int)$good,(int)$damage,$gd,$dd,$remarks];
 }
 if(!$values&&!$errors)$errors[]='Enter at least one pair of actual Good / Damaged counts. Blank means not counted.';
 return process_transaction(function()use($id,$filename,$errors,$values,$b){$q=db()->prepare('SELECT status FROM inventory_count_batches WHERE id=? FOR UPDATE');$q->execute([$id]);if(in_array($q->fetchColumn(),['Applied','Cancelled','Reversed'],true))throw new Exception('This count is closed.');db()->prepare('UPDATE inventory_count_lines SET actual_count=NULL,variance=NULL,actual_good=NULL,actual_damaged=NULL,good_variance=NULL,damaged_variance=NULL,remarks=NULL WHERE batch_id=?')->execute([$id]);$q=db()->prepare('UPDATE inventory_count_lines SET actual_good=?,actual_damaged=?,good_variance=?,damaged_variance=?,actual_count=?,variance=?,remarks=? WHERE id=? AND batch_id=?');foreach($values as $lineId=>[$g,$d,$gv,$dv,$remarks])$q->execute([$g,$d,$gv,$dv,$g+$d,$gv+$dv,$remarks,$lineId,$id]);$u=current_user();db()->prepare('UPDATE inventory_count_batches SET status=?,filename=?,error_json=?,reviewed_by=?,reviewed_name=?,reviewed_role=?,reviewed_at=NOW() WHERE id=?')->execute([$errors?'Error':'Pending Review',basename($filename),json_encode($errors),$u['id'],$u['name'],$u['role'],$id]);audit('Review condition counts','Inventory Count',$b['batch_ref'],count($values).' counted products; '.count($errors).' errors. Good and Damaged separated.');return $errors;});
}
function count_condition_apply($id,$reason,$allocations=[]){$cutoff=count_batch($id)['count_date']??date('Y-m-d');require_open_inventory_date($cutoff);
 $lines=count_lines($id);$hasNew=false;foreach($lines as $l)if($l['actual_good']!==null)$hasNew=true;if(!$hasNew)return count_apply_legacy($id,$reason,$allocations);
 if(current_user()['role']!=='Admin')throw new Exception('Administrator approval is required.');$reason=process_reason($reason);
 return process_transaction(function()use($id,$reason,$allocations){$q=db()->prepare('SELECT * FROM inventory_count_batches WHERE id=? FOR UPDATE');$q->execute([$id]);$b=$q->fetch();if(!$b||!in_array($b['status'],['Pending Review','Review Only'],true))throw new Exception('Count is not ready to apply.');$date=process_date($b['count_date']?:substr($b['created_at'],0,10));$lines=count_lines($id);$plans=[];$uid=current_user()['id'];
  foreach($lines as $l){if($l['actual_good']===null)continue;$pid=(int)$l['product_id'];$q=db()->prepare('SELECT active FROM products WHERE id=? FOR UPDATE');$q->execute([$pid]);if(!$q->fetchColumn())throw new Exception('Counted product is inactive.');if(!hash_equals($l['stock_signature'],count_stock_signature($pid)))throw new Exception('Stock changed after the count snapshot for '.$l['master_sku'].'. Download a fresh sheet and recount.');check_platform_alignment($pid);$gd=(int)$l['good_variance'];$dd=(int)$l['damaged_variance'];if(($gd||$dd)&&strlen(trim($l['remarks']))<3)throw new Exception('Discrepancy remarks are required.');if($gd)$plans[$pid]=incoming_plan([$pid=>['name'=>$l['product_name'],'qty'=>abs($gd),'damaged'=>false]],[$pid=>$allocations[$pid]??[]])[$pid];
  }
  foreach($lines as $l){if($l['actual_good']===null)continue;$pid=(int)$l['product_id'];$gd=(int)$l['good_variance'];$dd=(int)$l['damaged_variance'];$note=$reason.'; '.$l['remarks'];if($gd>0)db()->prepare('INSERT INTO inflows(txn_date,reference_no,product_id,source_qty,source_uom,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$date,$b['batch_ref'],$pid,$gd,'pc',$gd,'Inventory Count Adjustment',$note,$uid]);elseif($gd<0)db()->prepare('INSERT INTO outflows(txn_date,platform,order_id,product_id,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$date,'Internal',$b['batch_ref'],$pid,-$gd,'Inventory Count Adjustment',$note,$uid]);
   if($dd>0)db()->prepare('INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,0,?,?)')->execute([$date,'Internal',$b['batch_ref'],$pid,$dd,'Damage / Leak','Count Adjustment','For Review','Inventory Count',$note,$uid]);elseif($dd<0)db()->prepare('INSERT INTO nonsellable_outflows(txn_date,product_id,qty,type,reference_no,remarks,user_id) VALUES(?,?,?,?,?,?,?)')->execute([$date,$pid,-$dd,'Inventory Count Adjustment',$b['batch_ref'],$note,$uid]);
   if($gd)foreach(['Shopee','Lazada','TikTok'] as $pl)if($plans[$pid][$pl])change_platform_stock($pl,$pid,($gd<0?-1:1)*$plans[$pid][$pl],$b['batch_ref'],$date);check_platform_alignment($pid);audit('Condition count adjustment','Product',$l['master_sku'],'Good '.$l['sellable_on_hand'].' → '.$l['actual_good'].'; Damaged '.$l['nonsellable_on_hand'].' → '.$l['actual_damaged'].'; physical '.$l['on_hand'].' → '.$l['actual_count'].'; date '.$date.'; '.$b['batch_ref'].'; '.$note);
  }
  $u=current_user();db()->prepare("UPDATE inventory_count_batches SET status='Applied',approved_by=?,approved_name=?,approved_role=?,applied_at=NOW(),reason=? WHERE id=?")->execute([$uid,$u['name'],$u['role'],$reason,$id]);
 });
}
